('list:grand-massif.families','poi:les-carroz-village-slope',3,'A covered carpet and a free nursery slope.','{}'::text[],'{"where": "Les Carroz centre"}'::jsonb),
('list:grand-massif.families','poi:aquacime',4,'A spa for the end of the day.','{}'::text[],'{"where": "Les Carroz"}'::jsonb),
